CREATE TABLE client_progress_statements(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,statement_code VARCHAR(30) NOT NULL,statement_number VARCHAR(100) NULL,client_contract_id BIGINT UNSIGNED NOT NULL,project_id BIGINT UNSIGNED NOT NULL,client_id BIGINT UNSIGNED NOT NULL,pricing_method_snapshot VARCHAR(20) NULL,client_name_snapshot VARCHAR(190) NULL,project_code_snapshot VARCHAR(30) NULL,project_name_snapshot VARCHAR(190) NULL,contract_code_snapshot VARCHAR(30) NULL,contract_number_snapshot VARCHAR(100) NULL,contract_title_snapshot VARCHAR(190) NULL,statement_date DATE NOT NULL,period_from DATE NULL,period_to DATE NULL,statement_sequence INT UNSIGNED NULL,markup_percentage_snapshot DECIMAL(7,4) NULL,previous_cost_amount DECIMAL(18,2) NULL,current_cost_amount DECIMAL(18,2) NULL,cumulative_cost_amount DECIMAL(18,2) NULL,previous_markup_amount DECIMAL(18,2) NULL,current_markup_amount DECIMAL(18,2) NULL,cumulative_markup_amount DECIMAL(18,2) NULL,previous_variation_amount DECIMAL(18,2) NULL,current_variation_amount DECIMAL(18,2) NULL,cumulative_variation_amount DECIMAL(18,2) NULL,previous_statement_amount DECIMAL(18,2) NULL,current_statement_amount DECIMAL(18,2) NULL,cumulative_statement_amount DECIMAL(18,2) NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,approved_at DATETIME NULL,approved_by BIGINT UNSIGNED NULL,cancelled_at DATETIME NULL,cancelled_by BIGINT UNSIGNED NULL,notes TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_client_progress_statement_code(statement_code),UNIQUE KEY uq_client_progress_statement_number(client_contract_id,statement_number),UNIQUE KEY uq_client_progress_statement_sequence(client_contract_id,statement_sequence),KEY idx_client_progress_statement_history(client_contract_id,status,statement_sequence),KEY idx_client_progress_statement_project(project_id,status,statement_date),KEY idx_client_progress_statement_client(client_id,status),CONSTRAINT fk_cps_contract FOREIGN KEY(client_contract_id) REFERENCES client_contracts(id) ON DELETE RESTRICT,CONSTRAINT fk_cps_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE RESTRICT,CONSTRAINT fk_cps_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE RESTRICT,CONSTRAINT fk_cps_created_by FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_cps_approved_by FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_cps_cancelled_by FOREIGN KEY(cancelled_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT chk_cps_status CHECK(status IN('draft','approved','cancelled')),CONSTRAINT chk_cps_period CHECK(period_from IS NULL OR period_to IS NULL OR period_to>=period_from),CONSTRAINT chk_cps_audit CHECK((status='draft' AND statement_sequence IS NULL AND pricing_method_snapshot IS NULL AND markup_percentage_snapshot IS NULL AND client_name_snapshot IS NULL AND project_code_snapshot IS NULL AND project_name_snapshot IS NULL AND contract_code_snapshot IS NULL AND contract_number_snapshot IS NULL AND contract_title_snapshot IS NULL AND previous_cost_amount IS NULL AND current_cost_amount IS NULL AND cumulative_cost_amount IS NULL AND previous_markup_amount IS NULL AND current_markup_amount IS NULL AND cumulative_markup_amount IS NULL AND previous_variation_amount IS NULL AND current_variation_amount IS NULL AND cumulative_variation_amount IS NULL AND previous_statement_amount IS NULL AND current_statement_amount IS NULL AND cumulative_statement_amount IS NULL AND approved_at IS NULL AND approved_by IS NULL AND cancelled_at IS NULL AND cancelled_by IS NULL) OR(status='approved' AND statement_sequence IS NOT NULL AND pricing_method_snapshot='cost_plus' AND markup_percentage_snapshot IS NOT NULL AND client_name_snapshot IS NOT NULL AND project_code_snapshot IS NOT NULL AND project_name_snapshot IS NOT NULL AND contract_code_snapshot IS NOT NULL AND previous_cost_amount IS NOT NULL AND current_cost_amount IS NOT NULL AND cumulative_cost_amount IS NOT NULL AND previous_markup_amount IS NOT NULL AND current_markup_amount IS NOT NULL AND cumulative_markup_amount IS NOT NULL AND previous_variation_amount IS NOT NULL AND current_variation_amount IS NOT NULL AND cumulative_variation_amount IS NOT NULL AND previous_statement_amount IS NOT NULL AND current_statement_amount>0 AND cumulative_statement_amount IS NOT NULL AND approved_at IS NOT NULL AND approved_by IS NOT NULL AND cancelled_at IS NULL AND cancelled_by IS NULL) OR(status='cancelled' AND statement_sequence IS NULL AND pricing_method_snapshot IS NULL AND markup_percentage_snapshot IS NULL AND client_name_snapshot IS NULL AND project_code_snapshot IS NULL AND project_name_snapshot IS NULL AND contract_code_snapshot IS NULL AND contract_number_snapshot IS NULL AND contract_title_snapshot IS NULL AND previous_cost_amount IS NULL AND current_cost_amount IS NULL AND cumulative_cost_amount IS NULL AND previous_markup_amount IS NULL AND current_markup_amount IS NULL AND cumulative_markup_amount IS NULL AND previous_variation_amount IS NULL AND current_variation_amount IS NULL AND cumulative_variation_amount IS NULL AND previous_statement_amount IS NULL AND current_statement_amount IS NULL AND cumulative_statement_amount IS NULL AND approved_at IS NULL AND approved_by IS NULL AND cancelled_at IS NOT NULL AND cancelled_by IS NOT NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
